import{_ as e,C as r,o,c as h,aj as d,E as l}from"./framework.js";const _=JSON.parse('{"title":"邮箱：日历 | Product / Mail | Documentation","description":"邮箱：日历 in Kooboo: 页面会加载当前日期前后约 31 天的日程。切换月份时会重新加载日程范围。","frontmatter":{"title":"邮箱：日历 | Product / Mail | Documentation","description":"邮箱：日历 in Kooboo: 页面会加载当前日期前后约 31 天的日程。切换月份时会重新加载日程范围。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/mail/calendar.html"}]]},"headers":[],"relativePath":"zh/product/mail/calendar.md","filePath":"product/mail/calendar.md","lastUpdated":1780999973000}'),n={name:"zh/product/mail/calendar.md"};function i(c,t,s,b,m,p){const a=r("DocImage");return o(),h("div",null,[t[0]||(t[0]=d('<h1 id="邮箱-日历" tabindex="-1">邮箱：日历 <a class="header-anchor" href="#邮箱-日历" aria-label="Permalink to &quot;邮箱：日历&quot;">​</a></h1><blockquote><p>邮箱日历用于创建日程、邀请参与人，并处理邮件中的会议邀请。创建带参与人的日程时，系统会发送邀请邮件。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>邮箱</strong> -&gt; 左侧底部 <strong>Calendar</strong></td></tr><tr><td>深链</td><td><code>/_Admin/kmail/calendar</code></td></tr><tr><td>前端路由</td><td><code>/kmail/calendar</code></td></tr><tr><td>前置条件</td><td>建议先在 <a href="./addresses.html">邮箱地址</a> 中设置默认地址</td></tr></tbody></table>',4)),l(a,{src:"/product/mail/calendar-overview.png",alt:"邮箱日历：月视图与日程列表",width:"1120"}),t[1]||(t[1]=d('<h2 id="页面结构" tabindex="-1">页面结构 <a class="header-anchor" href="#页面结构" aria-label="Permalink to &quot;页面结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>月视图</td><td>按月展示日程；悬停日期格可点击加号新建日程</td></tr><tr><td>右侧日程列表</td><td>展示当前选中日期的日程</td></tr><tr><td>日程详情</td><td>点击右侧日程后弹出详情，可查看时间、地点、说明和参与人状态</td></tr><tr><td>折叠按钮</td><td>可收起或展开右侧日程列表</td></tr></tbody></table><p>页面会加载当前日期前后约 31 天的日程。切换月份时会重新加载日程范围。</p><h2 id="新建日程" tabindex="-1">新建日程 <a class="header-anchor" href="#新建日程" aria-label="Permalink to &quot;新建日程&quot;">​</a></h2><p>在日期格点击加号，或在无日程日期的右侧列表中点击 <code>New Schedule</code>，填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>Schedule Subject</td><td>日程标题，1 到 50 个字符</td></tr><tr><td>Participants</td><td>参与人邮箱地址，可为空</td></tr><tr><td>Start Time</td><td>开始日期和时间</td></tr><tr><td>End Time</td><td>结束日期和时间，必须晚于开始时间</td></tr><tr><td>Location</td><td>地点</td></tr><tr><td>Description</td><td>富文本说明</td></tr></tbody></table><p>如果填写了参与人，并且日程尚未过期，保存前会确认是否发送邀请邮件。发送邀请需要默认邮箱地址；没有默认地址时页面会提示先设置默认邮箱。</p><h2 id="编辑与删除" tabindex="-1">编辑与删除 <a class="header-anchor" href="#编辑与删除" aria-label="Permalink to &quot;编辑与删除&quot;">​</a></h2><p>点击日程后，在详情弹窗底部操作：</p><table tabindex="0"><thead><tr><th>操作</th><th>显示条件</th><th>说明</th></tr></thead><tbody><tr><td>编辑</td><td>当前用户是组织者</td><td>修改标题、时间、地点、说明和参与人</td></tr><tr><td>删除</td><td>日程详情中显示</td><td>删除日程；未过期且有参与人时会确认发送取消邮件</td></tr></tbody></table><p>编辑未过期日程时，系统会根据变更内容提示是否给原参与人、新增参与人或移除参与人发送邮件。</p><h2 id="会议邀请" tabindex="-1">会议邀请 <a class="header-anchor" href="#会议邀请" aria-label="Permalink to &quot;会议邀请&quot;">​</a></h2><p>收到带日历信息的邮件时，邮件详情页会显示会议邀请卡片。可选择：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>Yes</td><td>接受邀请</td></tr><tr><td>No</td><td>拒绝邀请</td></tr><tr><td>Maybe</td><td>暂定接受</td></tr><tr><td>Re-select</td><td>已选择后重新选择</td></tr></tbody></table><p>已过期邀请会显示过期状态，不能继续响应。</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>安排会议</td><td>设置默认地址 -&gt; Calendar -&gt; 日期格加号 -&gt; 填标题、参与人和时间 -&gt; 保存</td></tr><tr><td>修改会议时间</td><td>Calendar -&gt; 点日程 -&gt; 编辑 -&gt; 修改时间 -&gt; 确认通知参与人</td></tr><tr><td>取消会议</td><td>Calendar -&gt; 点日程 -&gt; 删除 -&gt; 确认发送取消邮件</td></tr><tr><td>处理邀请</td><td>收件箱 -&gt; 打开邀请邮件 -&gt; Yes / No / Maybe</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./addresses.html">邮箱地址</a></td><td>默认地址设置</td></tr><tr><td><a href="./messages.html#邮件详情">邮件列表</a></td><td>邮件详情中的会议邀请</td></tr><tr><td><a href="./compose.html">撰写邮件</a></td><td>邮件发送与草稿</td></tr></tbody></table>',19))])}const g=e(n,[["render",i]]);export{_ as __pageData,g as default};
